const getMapCoreRadius=glyph=>{
 const rect=glyph.getBoundingClientRect(),node=glyph.closest('[data-map-id]');
 if(matchMedia('(forced-colors:active)').matches)return Math.max(rect.width,rect.height)/2;
 const volume=glyph.querySelector('.celestial-volume'),painted=volume?.getBoundingClientRect();
 if(painted?.width){
  if(node.dataset.mapId==='running')return painted.width*27/512;
  if(volume.dataset.renderer==='geodesic')return painted.width*Math.sqrt(27)/56;
 }
 if(glyph.querySelector('.practice-orbits-canvas')?.getBoundingClientRect().width)return pane.width>900?17:14;
 if(node.dataset.mapId==='garage'&&document.documentElement.hasAttribute('data-celestial-volume'))return rect.width*.25;
 return Math.max(rect.width,rect.height)/2;
};
