let restoringMapFocus = false;
let dismissedMapHover = null;
let mapPointerPosition = null;
const restoreMapFocus = button => {
  restoringMapFocus = true;
  try { button?.focus({ preventScroll: true }); }
  finally { restoringMapFocus = false; }
};
inspectorClose?.addEventListener("click", () => {
  hideMapPreview({ immediate: true });
  if (observationRoute.active) { exitObservation(); return; }
  if (inspectorReturnHandler?.()) return;
  const selectedButton = mapButtons.get(selectedMapId);
  dismissedMapHover = { id: selectedMapId, ...mapPointerPosition };
  clearMapSelection({ updateHistory: true });
  restoreMapFocus(selectedButton);
  if (document.activeElement !== selectedButton) requestAnimationFrame(() => {
    if (document.activeElement === document.body || mapInspector.contains(document.activeElement)) restoreMapFocus(selectedButton);
  });
});



let mapDismissPointer = null;
const isMapDismissTarget = target => {
  if (!(target instanceof Element) || !pane.surface.contains(target)) return false;
  if (mapInspector.contains(target)) return mapInspector.classList.contains("is-case-view")
    && (target === mapInspector || target.matches(".case-layout"));
  return !target.closest("a, button, input, select, textarea, label, summary, [contenteditable], [data-map-id], [data-floating-console], .site-header, [data-content-panel], dialog, [popover]");
};
const startMapDismissPointer = event => {
  mapPointerPosition = { x: event.clientX, y: event.clientY };
  mapDismissPointer = event.isPrimary && event.button === 0 && isMapDismissTarget(event.target)
    ? { id: event.pointerId, x: event.clientX, y: event.clientY, moved: false } : null;
};
const trackMapDismissPointer = event => {
  mapPointerPosition = { x: event.clientX, y: event.clientY };
  if (mapDismissPointer?.id === event.pointerId
    && Math.hypot(event.clientX - mapDismissPointer.x, event.clientY - mapDismissPointer.y) > 8) mapDismissPointer.moved = true;
};
const cancelMapDismissPointer = () => { mapDismissPointer = null; };
const dismissMapPointerClick = event => {
  const pointer = mapDismissPointer;
  mapDismissPointer = null;
  if (!pointer || pointer.moved || event.button !== 0 || event.detail === 0
    || (event.pointerId !== undefined && event.pointerId !== pointer.id)
    || Math.hypot(event.clientX - pointer.x, event.clientY - pointer.y) > 8
    || !isMapDismissTarget(event.target)) return;
  if (mapInspector.classList.contains("is-open")) inspectorClose.click();
  else clearMapSelection({ updateHistory: true });
  hideMapPreview({ immediate: true });
  mapLabels.forEach(label => label.classList.remove("is-visible"));
  if (document.activeElement?.matches("[data-map-id]")) document.activeElement.blur();
};
document.addEventListener("pointerdown", startMapDismissPointer, true);
document.addEventListener("pointermove", trackMapDismissPointer, { capture: true, passive: true });
document.addEventListener("pointercancel", cancelMapDismissPointer, true);
document.addEventListener("click", dismissMapPointerClick);

